function clientKey(req){return (req.headers['x-forwarded-for']||req.socket.remoteAddress||'unknown').toString().split(',')[0].trim()}
const now=()=>new Date().toISOString(); const id=p=>p+'_'+crypto.randomBytes(7).toString('hex');
const hash=p=>crypto.scryptSync(p,crypto.randomBytes(16),64).toString('hex');
const verify=(p,h)=>{try{if(!h)return false;if(h.startsWith('scrypt$'))return crypto.timingSafeEqual(Buffer.from(hashWithSalt(p,h),'hex'),Buffer.from(h.split('$')[2],'hex'));return h===p}catch{return false}};
