  if(!fs.existsSync(DBFILE)) fs.writeFileSync(DBFILE,JSON.stringify(seed(),null,2));
  const d=JSON.parse(fs.readFileSync(DBFILE,'utf8'));
  const arrs=['users','admins','advertisers','tasks','attempts','activities','withdrawals','transactions','rewards','redemptions','referrals','tickets','notifications','audits','violations','campaigns','partners','offers','subscriptions','coupons','postbacks','sessions','resetTokens'];
  for(const k of arrs) if(!Array.isArray(d[k])) d[k]=[];
  d.settings={...seed().settings,...(d.settings||{})};
  d.settings.packages={...seed().settings.packages,...(d.settings?.packages||{})}; for(const k of Object.keys(seed().settings.packages)) d.settings.packages[k]={...seed().settings.packages[k],...(d.settings.packages[k]||{})};
