function body(req){return new Promise((resolve,reject)=>{let b='';req.on('data',c=>{b+=c;if(b.length>2e6)reject(Error('too large'))});req.on('end',()=>{if(!b)return resolve({});try{resolve(JSON.parse(b))}catch{reject(Error('invalid JSON'))}})})}
