function user(req){const h=req.headers.authorization||'';if(!h.startsWith('Bearer '))return null;const s=db.sessions.find(x=>x.token===h.slice(7)&&new Date(x.expires)>new Date());return s?db.users.find(u=>u.id===s.userId):null}
